package com.bank.pool.service;

import java.util.logging.Logger;

// Computes recommended thread-pool sizes using the standard formulas.
public class ThreadPoolSizer {
    private static final Logger log = Logger.getLogger(ThreadPoolSizer.class.getName());

    private final int cores;

    public ThreadPoolSizer() {
        this(Runtime.getRuntime().availableProcessors());
    }

    // Overload for tests so the result is deterministic regardless of machine.
    public ThreadPoolSizer(int cores) {
        if (cores < 1) throw new IllegalArgumentException("cores must be >= 1");
        this.cores = cores;
    }

    // CPU-bound: cores + 1. A computing thread never yields the core voluntarily.
    public int cpuBoundSize() {
        int size = cores + 1;
        log.info(() -> "CPU-bound size on " + cores + " cores = " + size);
        return size;
    }

    // IO-bound: cores * (1 + waitTime/computeTime).
    public int ioBoundSize(long waitMs, long computeMs) {
        if (computeMs <= 0) throw new IllegalArgumentException("computeMs must be > 0");
        int size = (int) Math.round(cores * (1 + (double) waitMs / computeMs));
        log.info(() -> "IO-bound size on " + cores + " cores (wait=" + waitMs
                + "ms compute=" + computeMs + "ms) = " + size);
        return size;
    }
}
