package com.bank.pool.service;

import java.math.BigDecimal;
import java.math.RoundingMode;

// Pure computation: compound interest. No blocking at all → CPU-bound.
public class CpuBoundTask implements java.util.concurrent.Callable<BigDecimal> {
    private final String accountId;
    private final BigDecimal principal;
    private final BigDecimal rate;
    private final int periods;

    public CpuBoundTask(String accountId, BigDecimal principal, BigDecimal rate, int periods) {
        this.accountId = accountId;
        this.principal = principal;
        this.rate = rate;
        this.periods = periods;
    }

    @Override
    public BigDecimal call() {
        BigDecimal amount = principal;
        BigDecimal factor = BigDecimal.ONE.add(rate);
        for (int i = 0; i < periods; i++) {
            amount = amount.multiply(factor);  // tight CPU loop, no IO
        }
        return amount.setScale(2, RoundingMode.HALF_UP);
    }

    public String getAccountId() { return accountId; }
}
