package com.bank.pool.service;

// Mostly waiting: simulates a slow DB + remote call → IO-bound.
public class IoBoundTask implements java.util.concurrent.Callable<String> {
    private final String accountId;
    private final long waitMs;

    public IoBoundTask(String accountId, long waitMs) {
        this.accountId = accountId;
        this.waitMs = waitMs;
    }

    @Override
    public String call() throws InterruptedException {
        Thread.sleep(waitMs);                 // blocked on IO: core is free here
        return "STATEMENT-" + accountId;       // tiny compute after the wait
    }
}
