package com.bank.pool.service;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Runnable demo: shows wrong vs right sizing for both workloads.
public class PoolSizingApplication {
    private static final Logger log = Logger.getLogger(PoolSizingApplication.class.getName());

    public static void main(String[] args) throws Exception {
        ThreadPoolSizer sizer = new ThreadPoolSizer(8);        // pretend 8-core box

        int cpuSize = sizer.cpuBoundSize();                    // 9
        int ioSize  = sizer.ioBoundSize(90, 10);               // 80

        log.info(() -> "Recommended CPU-bound pool: " + cpuSize);
        log.info(() -> "Recommended IO-bound pool:  " + ioSize);

        CpuBoundTask interest = new CpuBoundTask(
                "SAV2001", new BigDecimal("1000000"), new BigDecimal("0.0005"), 100000);
        log.info("Rajesh SAV2001 interest result: " + interest.call());

        IoBoundTask statement = new IoBoundTask("CUR3001", 90);
        log.info("Priya CUR3001 statement result: " + statement.call());
    }
}
