package com.bank.pool.service;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;
import static org.junit.jupiter.api.Assertions.assertThrows;

class ThreadPoolSizerTest {

    @Test
    void cpuBound_isCoresPlusOne() {
        ThreadPoolSizer sizer = new ThreadPoolSizer(8);
        assertThat(sizer.cpuBoundSize()).isEqualTo(9);
    }

    @Test
    void ioBound_usesWaitOverComputeRatio() {
        ThreadPoolSizer sizer = new ThreadPoolSizer(8);
        // 8 * (1 + 90/10) = 8 * 10 = 80
        assertThat(sizer.ioBoundSize(90, 10)).isEqualTo(80);
    }

    @Test
    void ioBound_isMuchLargerThanCpuBound() {
        ThreadPoolSizer sizer = new ThreadPoolSizer(8);
        assertThat(sizer.ioBoundSize(90, 10)).isGreaterThan(sizer.cpuBoundSize());
    }

    @Test
    void zeroCompute_isRejected() {
        ThreadPoolSizer sizer = new ThreadPoolSizer(8);
        assertThrows(IllegalArgumentException.class, () -> sizer.ioBoundSize(90, 0));
    }

    @Test
    void zeroCores_isRejected() {
        assertThrows(IllegalArgumentException.class, () -> new ThreadPoolSizer(0));
    }
}
